import{_ as a,o as e,c as d,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"包管理器选型","description":"","frontmatter":{"title":"包管理器选型","outline":[2,3],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"frontend/decisions/tooling/package-manager.md","filePath":"frontend/decisions/tooling/package-manager.md","lastUpdated":1785589115000}'),o={name:"frontend/decisions/tooling/package-manager.md"};function n(i,t,l,h,p,c){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="包管理器选型" tabindex="-1">包管理器选型 <a class="header-anchor" href="#包管理器选型" aria-label="Permalink to &quot;包管理器选型&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>包管理器决定依赖如何解析、锁定、存储、执行脚本和组织工作区。npm、pnpm、Yarn、Bun 等候选的核心功能不断演进，选型应基于当前受支持版本的实测行为，并把锁文件和 CI 可复现性置于命令偏好之上。</p><p>基础机制参见<a href="/frontend/guide/engineering/tooling/package-management">包管理器、锁文件与工作区</a>。</p><h2 id="_1-决策背景" tabindex="-1">1. 决策背景 <a class="header-anchor" href="#_1-决策背景" aria-label="Permalink to &quot;1. 决策背景&quot;">​</a></h2><p>单应用更换包管理器的收益通常有限；大型工作区可能从严格依赖、磁盘复用、workspace 协议和过滤执行中获得明显收益。团队也要考虑私有仓库、代理、原生依赖、补丁、发布工具和开发环境支持。</p><p>决策范围必须包括开发机、CI、容器和发布流水线，不能只验证一次本地安装。</p><h2 id="_2-硬约束与评价标准" tabindex="-1">2. 硬约束与评价标准 <a class="header-anchor" href="#_2-硬约束与评价标准" aria-label="Permalink to &quot;2. 硬约束与评价标准&quot;">​</a></h2><h3 id="_2-1-硬约束" tabindex="-1">2.1 硬约束 <a class="header-anchor" href="#_2-1-硬约束" aria-label="Permalink to &quot;2.1 硬约束&quot;">​</a></h3><ul><li>在公司支持的 Node.js、操作系统、容器和网络代理中可运行；</li><li>锁文件可提交，CI 能拒绝未同步依赖并离线或缓存安装；</li><li>私有 registry、认证、审计和供应链扫描兼容；</li><li>关键安装脚本、原生模块和发布流程经过验证；</li><li>包管理器版本能够被项目固定，新成员和 CI 不依赖全局偶然版本。</li></ul><h3 id="_2-2-评价维度" tabindex="-1">2.2 评价维度 <a class="header-anchor" href="#_2-2-评价维度" aria-label="Permalink to &quot;2.2 评价维度&quot;">​</a></h3><p>比较安装可复现、严格依赖隔离、工作区能力、缓存和磁盘、安装性能、补丁与 overrides、发布生态、错误可诊断性、工具兼容和迁移成本。一次热缓存安装速度不是充分证据。</p><h2 id="_3-候选方案" tabindex="-1">3. 候选方案 <a class="header-anchor" href="#_3-候选方案" aria-label="Permalink to &quot;3. 候选方案&quot;">​</a></h2><h3 id="_3-1-npm" tabindex="-1">3.1 npm <a class="header-anchor" href="#_3-1-npm" aria-label="Permalink to &quot;3.1 npm&quot;">​</a></h3><p>随 Node.js 生态广泛使用，工具兼容和上手成本低，支持锁文件与 workspace。适合需求常规、希望减少额外工具约束的项目。</p><h3 id="_3-2-pnpm" tabindex="-1">3.2 pnpm <a class="header-anchor" href="#_3-2-pnpm" aria-label="Permalink to &quot;3.2 pnpm&quot;">​</a></h3><p>通过内容寻址存储和链接复用依赖，并以较严格的依赖可见性帮助发现幽灵依赖；工作区和过滤能力适合 Monorepo。需要确认少数依赖对链接布局、打包和部署的兼容。</p><h3 id="_3-3-yarn" tabindex="-1">3.3 Yarn <a class="header-anchor" href="#_3-3-yarn" aria-label="Permalink to &quot;3.3 Yarn&quot;">​</a></h3><p>不同主版本具有不同安装模型和工作区能力，可选择传统 <code>node_modules</code> 或更严格的解析方式。评估时必须写明具体主版本和 linker，不能只写“Yarn”。</p><h3 id="_3-4-bun" tabindex="-1">3.4 Bun <a class="header-anchor" href="#_3-4-bun" aria-label="Permalink to &quot;3.4 Bun&quot;">​</a></h3><p>Bun 同时提供运行时和包管理能力，安装性能可能有吸引力。若项目仍以 Node.js 为生产和工具标准，应重点验证锁文件、生命周期脚本、原生模块、registry 和周边工具兼容，而不是因速度直接替换。</p><h2 id="_4-关键维度对比" tabindex="-1">4. 关键维度对比 <a class="header-anchor" href="#_4-关键维度对比" aria-label="Permalink to &quot;4. 关键维度对比&quot;">​</a></h2><p>案例是 60 个 workspace 的 TypeScript Monorepo，开发机包括 Windows 和 macOS，CI 使用 Linux；团队依赖私有 registry、补丁、独立包发布和 Docker 部署。</p><table tabindex="0"><thead><tr><th>维度</th><th>npm</th><th>pnpm</th><th>Yarn</th><th>Bun</th></tr></thead><tbody><tr><td>工作区过滤</td><td>基础可用</td><td>成熟且贴合当前需求</td><td>依版本而定</td><td>需按当前版本验证</td></tr><tr><td>幽灵依赖暴露</td><td>较宽松</td><td>较严格</td><td>取决于 linker</td><td>需验证</td></tr><tr><td>磁盘与缓存</td><td>中</td><td>优</td><td>依模式</td><td>安装快，需验证共享缓存</td></tr><tr><td>现有发布工具</td><td>通过</td><td>通过</td><td>通过原型</td><td>两项插件未通过</td></tr><tr><td>三平台原生依赖</td><td>通过</td><td>通过</td><td>通过</td><td>一个关键模块失败</td></tr><tr><td>迁移成本</td><td>当前基线</td><td>中</td><td>中</td><td>高</td></tr></tbody></table><p>表中结论只对已测试版本有效，升级包管理器仍需回归。</p><h2 id="_5-场景化推荐结论" tabindex="-1">5. 场景化推荐结论 <a class="header-anchor" href="#_5-场景化推荐结论" aria-label="Permalink to &quot;5. 场景化推荐结论&quot;">​</a></h2><p>本案例选择 pnpm，原因是工作区过滤、严格依赖和磁盘复用符合 60 包规模，并且三平台、私有 registry、补丁和发布原型全部通过。Bun 保留为后续观察项，不将包管理器选型与生产运行时迁移绑定。</p><p>项目在根 <code>package.json</code> 的 <code>packageManager</code> 字段固定精确版本，CI 使用 frozen lockfile，依赖变更必须同时提交锁文件。迁移后一次性修复幽灵依赖，不用宽松提升配置掩盖问题。</p><h2 id="_6-引入后的后果" tabindex="-1">6. 引入后的后果 <a class="header-anchor" href="#_6-引入后的后果" aria-label="Permalink to &quot;6. 引入后的后果&quot;">​</a></h2><p>pnpm 能减少重复存储并让未声明依赖更早暴露，但团队需要理解 workspace 协议、过滤命令和部署产物。部分工具若错误假设扁平 <code>node_modules</code>，需要升级、配置或替换。</p><p>锁文件变更会影响整个仓库，应通过依赖审查和自动化减少无关 churn。包管理器不替代依赖治理，版本范围、漏洞响应和发布策略仍需单独负责。</p><p>退出成本主要是锁文件、工作区协议和脚本命令。保持标准 package manifest、避免在业务代码读取安装布局，可降低切换成本。</p><h2 id="_7-不适用场景" tabindex="-1">7. 不适用场景 <a class="header-anchor" href="#_7-不适用场景" aria-label="Permalink to &quot;7. 不适用场景&quot;">​</a></h2><ul><li>小型稳定项目安装并非瓶颈时，不必为了基准数字迁移。</li><li>不要混用多个锁文件或允许开发机与 CI 使用不同主版本。</li><li>不要把依赖解析差异当作“工具 bug”后直接关闭严格性，应先修复未声明依赖。</li><li>生产使用 Node.js 不意味着必须使用 npm，反之包管理器迁移也不要求更换运行时。</li><li>未验证原生模块和发布链路前，不应只凭安装成功做决定。</li></ul><h2 id="_8-填写完成的决策记录" tabindex="-1">8. 填写完成的决策记录 <a class="header-anchor" href="#_8-填写完成的决策记录" aria-label="Permalink to &quot;8. 填写完成的决策记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>问题</td><td>60 包 Monorepo 使用哪个包管理器</td></tr><tr><td>硬约束</td><td>Windows/macOS/Linux；私有 registry；原生模块；补丁；独立发布</td></tr><tr><td>候选</td><td>npm、pnpm、Yarn、Bun</td></tr><tr><td>决定</td><td>固定版本的 pnpm</td></tr><tr><td>证据</td><td>冷热安装、三平台 CI、发布和 Docker 原型；幽灵依赖清单</td></tr><tr><td>接受代价</td><td>修复未声明依赖；培训 workspace 与过滤命令</td></tr><tr><td>CI 约束</td><td>frozen lockfile；只允许一个锁文件；版本由项目声明</td></tr><tr><td>退出路径</td><td>标准 manifests；业务代码不依赖存储布局</td></tr></tbody></table><h2 id="_9-复查条件" tabindex="-1">9. 复查条件 <a class="header-anchor" href="#_9-复查条件" aria-label="Permalink to &quot;9. 复查条件&quot;">​</a></h2><p>包管理器停止安全维护、关键工具连续两个版本不兼容、安装和缓存成本超过预算、组织运行时标准改变，或替代方案已通过完整跨平台和发布回归时复查。常规小版本性能变化不应触发迁移。</p>',38)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
